#!/usr/bin/env node
/*
  Leo post card (Leo Manager, HO-0087 part C, 2026-11-16). Renders one X post written by a sport chat
  (data/<sport>/social/<date>.json, built by scripts/build-<sport>-social.js) as a 1080 x 1350 graphic.

    node post-card.js <social-file.json> <post id: picks | wave-1 ... | day | last> <out.png>

  The words, lines, record, facts and hashtags are the sport chat's; this script only draws them and
  prints {png, id, kind, text} where text is the post exactly as written in the file.
  Voice (Lynold, Nov 16): no "Leo saw it", no BANG or ✨; picks say "What would Leo do?" then "Leo picks:";
  results open with the plain record and percent, winners on top, losers on the bottom.
*/
"use strict";
const fs = require("fs");
const { chromium } = require("playwright");
const esc = s => String(s ?? "").replace(/[&<>"]/g, c => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" }[c]));
// Shared look for Leo's X posters (Leo Manager, 2026-11-15). Inlined into share-card.js and picks-card.js.
// Lynold: "something like this" (sports poster graphics: huge condensed type, gold script, dark texture),
// date always shown, and Leo has its own persona: a gold lion, voice "Leo saw it".
const fontsDir = (() => {
  const path = require("path"), fs = require("fs"), cp = require("child_process");
  const dir = "/tmp/leo-fonts";
  const want = ["@fontsource/anton", "@fontsource/kaushan-script", "@fontsource/oswald"];
  if (!want.every(p => fs.existsSync(path.join(dir, "node_modules", p)))) {
    fs.mkdirSync(dir, { recursive: true });
    cp.execSync(`npm i --silent --prefix ${dir} ${want.join(" ")}`, { stdio: "ignore" });
  }
  return path.join(dir, "node_modules", "@fontsource");
})();
function fontCss() {
  const fs = require("fs"), b = f => fs.readFileSync(`${fontsDir}/${f}`).toString("base64");
  const face = (fam, file, w) => `@font-face{font-family:'${fam}';font-weight:${w};src:url(data:font/woff2;base64,${b(file)}) format('woff2')}`;
  return [face("Anton", "anton/files/anton-latin-400-normal.woff2", 400),
    face("Kaushan", "kaushan-script/files/kaushan-script-latin-400-normal.woff2", 400),
    face("Oswald", "oswald/files/oswald-latin-500-normal.woff2", 500),
    face("Oswald", "oswald/files/oswald-latin-700-normal.woff2", 700)].join("\n");
}
// Leo's mark: an original geometric lion head in gold (no team or league logo).
function lion(size = 120) {
  const rays = Array.from({ length: 14 }, (_, i) => {
    const a = (i / 14) * Math.PI * 2, a1 = a - 0.2, a2 = a + 0.2, r1 = 34, r2 = 58;
    const p = (r, t) => `${50 + r * Math.cos(t)},${50 + r * Math.sin(t)}`;
    return `<polygon points="${p(r1, a1)} ${p(r2, a)} ${p(r1, a2)}" fill="url(#lg)"/>`;
  }).join("");
  return `<svg width="${size}" height="${size}" viewBox="0 0 100 100"><defs><linearGradient id="lg" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#FFE08A"/><stop offset="1" stop-color="#C9962B"/></linearGradient></defs>
${rays}<circle cx="50" cy="50" r="34" fill="url(#lg)"/>
<path d="M50 24 C64 24 72 34 72 47 C72 62 62 74 50 78 C38 74 28 62 28 47 C28 34 36 24 50 24Z" fill="#0E1624"/>
<path d="M37 45 L46 47 L38 50Z M63 45 L54 47 L62 50Z" fill="#FFD467"/>
<path d="M45 58 L55 58 L50 64Z" fill="#FFD467"/><path d="M50 64 L50 68 M44 69 Q50 73 56 69" stroke="#FFD467" stroke-width="2" fill="none" stroke-linecap="round"/></svg>`;
}
// Dark textured backdrop with gold confetti, seeded so a card is the same every run.
function backdrop(seed) {
  let s = seed || 7; const rnd = () => ((s = (s * 9301 + 49297) % 233280) / 233280);
  const bits = Array.from({ length: 16 }, () => {
    const side = rnd() < 0.5; const x = side ? Math.round(rnd() * 40) - 10 : 1030 + Math.round(rnd() * 40) - 10, y = 160 + Math.round(rnd() * 950), w = 10 + Math.round(rnd() * 16), h = 40 + Math.round(rnd() * 50), r = Math.round(rnd() * 180), o = (0.25 + rnd() * 0.55).toFixed(2);
    return `<div class="cf" style="left:${x}px;top:${y}px;width:${w}px;height:${h}px;transform:rotate(${r}deg);opacity:${o}"></div>`;
  }).join("");
  return `<div class="bg"></div><div class="grain"></div>${bits}`;
}
const baseCss = `
html,body{margin:0;width:1080px;height:1350px;overflow:hidden}
body{background:#0B111C;color:#fff;font-family:Oswald,Helvetica,Arial,sans-serif;position:relative}
.bg{position:absolute;inset:0;background:radial-gradient(900px 700px at 50% 30%,#1D3566 0%,#111B2E 55%,#080C14 100%)}
.grain{position:absolute;inset:0;display:none;opacity:0;background-image:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='200' height='200'><filter id='n'><feTurbulence type='fractalNoise' baseFrequency='.9' numOctaves='2'/></filter><rect width='200' height='200' filter='url(%23n)'/></svg>")}
.cf{position:absolute;z-index:1;background:linear-gradient(180deg,#FFE7A3,#C9962B);border-radius:3px;filter:blur(.4px)}
.frame{position:absolute;inset:28px;border:2px solid rgba(233,185,73,.55);border-radius:22px}
.wrap{position:absolute;z-index:2;inset:0;padding:64px 70px;display:flex;flex-direction:column}
.top{display:flex;align-items:center;justify-content:space-between}
.brand{display:flex;align-items:flex-end;gap:6px;font-family:Anton;font-size:72px;line-height:1;letter-spacing:.02em}.brand .dot{width:16px;height:16px;border-radius:50%;background:#F4C542;margin-bottom:10px}
.date{font-family:Oswald;font-weight:700;font-size:28px;letter-spacing:.18em;color:#E9B949;text-align:right;line-height:1.25}
.date small{display:block;color:#C9D2DE;font-size:22px;letter-spacing:.22em}
.hero{position:relative;margin-top:26px;text-align:center}
.hero h1{font-family:Anton;font-weight:400;margin:0;line-height:.86;letter-spacing:.01em;text-transform:uppercase;text-shadow:0 8px 30px rgba(0,0,0,.5)}
.hero .script{position:relative;margin-top:34px;font-family:Kaushan;color:#F4C542;transform:rotate(-4deg);text-shadow:0 4px 18px rgba(0,0,0,.6)}
.stats{display:flex;justify-content:center;gap:34px;margin-top:34px}
.st{text-align:center}.st b{display:block;font-family:Anton;font-weight:400;font-size:118px;line-height:1}
.st span{display:inline-block;margin-top:8px;background:#E9B949;color:#0B111C;font-weight:700;font-size:26px;letter-spacing:.12em;padding:4px 14px;border-radius:6px}
.foot{margin-top:auto;display:flex;justify-content:space-between;align-items:center;font-weight:700;font-size:26px;letter-spacing:.08em;color:#C9D2DE}
.foot b{color:#fff;font-size:30px}
`;
const dateLine = date => new Date(`${date}T12:00:00Z`).toLocaleDateString("en-US", { weekday: "long", month: "short", day: "numeric", timeZone: "UTC" }).toUpperCase();
// v5 look (Lynold, Nov 16): ChatGPT kit's header, avatar, boxed stats and call cards, with the Manager's poster type.
const AVATAR = "data:image/png;base64,";
const v5Css = `
.hdr{display:flex;align-items:center;gap:16px;padding-bottom:18px;border-bottom:1px solid rgba(233,185,73,.35)}
.hdr img{width:92px;height:92px;border-radius:50%}
.hdr .wm{font-family:Anton;font-size:56px;line-height:.9;letter-spacing:.02em}.hdr .wm small{display:block;font-family:Oswald;font-weight:700;font-size:17px;letter-spacing:.2em;color:#9FB0C6;margin-top:6px}
.hdr .date{margin-left:auto}
.eyebrow{margin-top:26px;text-align:center;font-weight:700;font-size:22px;letter-spacing:.3em;color:#E9B949;text-transform:uppercase}
.hero h1{font-size:150px}
.hero .script{margin-top:26px;font-size:70px}
.rule{height:2px;background:linear-gradient(90deg,transparent,#E9B949,transparent);margin:26px 40px 0}
.boxes{display:flex;gap:26px;margin-top:26px}
.box{flex:1;border:2px solid #E9B949;border-radius:14px;background:rgba(26,41,68,.75);text-align:center;padding:14px 0 18px}
.box b{display:block;font-family:Anton;font-weight:400;font-size:96px;line-height:1}
.box span{display:inline-block;margin-top:10px;background:#E9B949;color:#0B111C;font-weight:700;font-size:24px;letter-spacing:.16em;padding:5px 26px;border-radius:6px}
.cards{display:grid;gap:12px;margin-top:24px}
.cd{display:flex;align-items:center;justify-content:space-between;border-radius:12px;padding:0 20px;font-weight:700;text-transform:uppercase;letter-spacing:.03em;box-shadow:0 6px 16px rgba(0,0,0,.25)}
.cd.w{background:#2F9E5B}.cd.l{background:#C2463A}.cd.p{background:#5B6577}
.cd .mk{font-size:1.25em;margin-left:10px}
.cd .t{display:flex;flex-direction:column;line-height:1.1}.cd .t small{font-weight:500;font-size:.62em;opacity:.85;letter-spacing:.06em;margin-top:4px}
.gm{border:2px solid rgba(233,185,73,.7);border-radius:14px;background:rgba(26,41,68,.8);padding:18px 22px}
.gm .h{display:flex;justify-content:space-between;align-items:baseline}.gm .mt{font-family:Anton;letter-spacing:.01em}.gm .tm{font-weight:700;color:#E9B949;letter-spacing:.06em}
.gm .tags{display:flex;flex-wrap:wrap;gap:10px;margin-top:12px}
.tg{display:flex;align-items:baseline;gap:12px;background:#2A3D5C;border:1px solid rgba(233,185,73,.5);border-radius:9px;padding:7px 14px}
.tg small{font-weight:700;color:#E9B949;letter-spacing:.1em;font-size:.72em;text-transform:uppercase}.tg b{font-weight:700}
`;
function header(label, dateTxt) {
  return `<div class="hdr"><img src="${AVATAR}"><div class="wm">LEO.<small>SPORTS MODEL</small></div><div class="date">${esc(label)}<small>${esc(dateTxt)}</small></div></div>`;
}

const [, , file, idArg = "last", out = "post.png"] = process.argv;
const doc = JSON.parse(fs.readFileSync(file, "utf8"));
const sport = String(doc.sport || "").toUpperCase();
const posts = doc.posts || [];
const post = idArg === "last" ? posts[posts.length - 1] : posts.find(p => p.id === idArg);
if (!post) { console.log(JSON.stringify({ png: null, id: idArg, text: "" })); process.exit(0); }
const seed = [...`${doc.date}${post.id}`].reduce((a, c) => a + c.charCodeAt(0), 0);
const stripEmoji = s => String(s || "").replace(/[\u{1F300}-\u{1FAFF}\u{2600}-\u{27BF}\u{FE0F}]/gu, "").trim();
// Calls only: header lines like "Leo picks:" or "No Leo Pick tonight. ...:" stay in the text, not on the graphic.
const lines = (post.lines || []).filter(l => !/:\s*$/.test(l) && !/^what would leo do/i.test(l));
const facts = post.facts || [];
const n = lines.length;
const isPicks = post.kind === "picks";
// "What would Leo do?" appears once: in the eyebrow on a no-pick night, as the script line on a pick night.
const eyebrowRaw = stripEmoji(post.header).replace(/\s+/g, " ").trim();
// A night with no pick says so (Nov 19: "LEO PICKS" over three passes read as three picks).
const noPick = isPicks && (post.nopick || (post.lines || []).some(l => /^No (Leo )?picks? /i.test(l)));
const npTitle = /Mondays/i.test((post.lines || []).join(" ")) ? "No picks Monday" : "No picks tonight";
const eyebrowTxt = isPicks && !noPick ? eyebrowRaw.replace(/\s*What would Leo do\?\s*$/i, "") : eyebrowRaw;

// One line: text, its result mark (✅ ❌ ➖) and anything after the mark (units).
function split(line) {
  const m = /^(.*?)\s*(✅|❌|➖)\s*(.*)$/.exec(line);
  return m ? { t: m[1], r: m[2] === "✅" ? "w" : m[2] === "❌" ? "l" : "p", after: m[3] } : { t: line, r: null, after: "" };
}
let body = "", hero = "", extraCss = "";
if (isPicks) {
  const big = n <= 2 ? 64 : n <= 4 ? 50 : n <= 7 ? 40 : n <= 10 ? 32 : 27;
  const cols = n <= 7 ? 1 : 2;
  const rows = lines.map(l => {
    const m = /^(.*?)\s*\(([\d.]+%)\)\s*$/.exec(l);
    return `<div class="pk"><span>${esc(m ? m[1] : l)}</span>${m ? `<b>${esc(m[2])}</b>` : ""}</div>`;
  }).join("");
  hero = noPick
    ? `<div class="hero"><h1>${npTitle}</h1>${post.note ? `<div class="note">${esc(post.note)}</div>` : ""}</div>`
    : `<div class="hero"><h1>Leo picks</h1><div class="script">What would Leo do?</div></div>`;
  body = `<div class="pks" style="grid-template-columns:repeat(${cols},minmax(0,1fr))">${rows}</div>`;
  extraCss = `.pks{display:grid;gap:${n <= 4 ? 16 : 10}px;margin-top:${n <= 4 ? 34 : 22}px}
.pk{display:flex;justify-content:space-between;align-items:center;gap:16px;border:2px solid rgba(233,185,73,.75);border-radius:12px;background:rgba(26,41,68,.8);padding:${n <= 4 ? "20px 26px" : n <= 10 ? "11px 18px" : "8px 14px"};font-family:Anton;font-size:${big}px;text-transform:uppercase;letter-spacing:.01em;white-space:nowrap}
.pk span{overflow:hidden;text-overflow:ellipsis}.pk b{font-weight:400;color:#F4C542}
.hero .note{font-weight:700;font-size:34px;letter-spacing:.02em;color:#E9B949;margin-top:18px}
${noPick ? ".hero h1{font-size:112px}" : ""}
${n > 10 ? ".hero h1{font-size:118px}.hero .script{font-size:52px;margin-top:14px}" : ""}`;
} else {
  const recM = /^(\d+-\d+(?:-\d+)?)\s*(\([^)]*\))?\s*(.*)$/.exec(String(post.record || ""));
  const rec = recM ? recM[1] : String(post.record || "");
  const pct = recM && recM[2] ? recM[2].replace(/[()]/g, "") : "";
  const rest = recM ? recM[3].replace(/^,\s*/, "") : "";
  const parsed = lines.map(split);
  const cols = n <= 4 ? 1 : n <= 14 ? 2 : 3;
  const h = n <= 4 ? 96 : n <= 8 ? 76 : n <= 12 ? 60 : 54;
  const fz = n <= 4 ? 38 : n <= 8 ? 28 : n <= 14 ? 24 : 20;
  hero = `<div class="rec"><b>${esc(rec)}</b>${pct ? `<span>${esc(pct)}</span>` : ""}</div>${rest ? `<div class="sub">${esc(rest)}</div>` : ""}`;
  body = `<div class="cards" style="grid-template-columns:repeat(${cols},minmax(0,1fr))">${parsed.map(p => `<div class="cd ${p.r || "p"}" style="height:${h}px;font-size:${fz}px"><span class="t">${esc(p.t)}</span><span class="mk">${p.r === "w" ? "✓" : p.r === "l" ? "✗" : p.r === "p" ? "push" : ""}${p.after ? `<small>${esc(p.after)}</small>` : ""}</span></div>`).join("")}</div>`;
  extraCss = `.rec{display:flex;align-items:center;justify-content:center;gap:26px;margin-top:10px}
.rec b{font-family:Anton;font-weight:400;font-size:${n > 10 ? 170 : 210}px;line-height:1;text-shadow:0 8px 30px rgba(0,0,0,.5)}
.rec span{font-family:Anton;font-size:${n > 10 ? 64 : 76}px;background:#E9B949;color:#0B111C;padding:4px 22px;border-radius:12px}
.sub{text-align:center;font-weight:700;font-size:30px;letter-spacing:.06em;color:#C9D2DE;margin-top:6px}
.cd .t{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.cd .mk{display:flex;align-items:baseline;gap:8px;white-space:nowrap}.cd .mk small{font-size:.75em;font-weight:700}`;
}
const factHtml = facts.length ? `<div class="facts">${facts.map(f => `<div>${esc(f)}</div>`).join("")}</div>` : "";
const label = isPicks ? `${sport} PICKS` : `${sport} RESULTS`;
const html = `<!doctype html><html><head><meta charset="utf-8"><style>${fontCss()}${baseCss}${v5Css}
.main{flex:1;display:flex;flex-direction:column;justify-content:${n <= 3 ? "center" : "flex-start"};padding-bottom:14px}
.eyebrow{font-size:${eyebrowTxt.length > 26 ? 24 : 30}px}
.facts{margin-top:18px;border-top:2px solid rgba(233,185,73,.4);padding-top:12px}
.facts div{font-weight:700;font-size:${facts.length > 2 || n > 10 ? 23 : 27}px;letter-spacing:.03em;color:#E8EDF4;padding:4px 0 4px 24px;position:relative;text-transform:uppercase}
.facts div:before{content:"";position:absolute;left:0;top:50%;width:11px;height:11px;margin-top:-5px;border-radius:50%;background:#F4C542}
${extraCss}
</style></head><body>${backdrop(seed)}<div class="frame"></div><div class="wrap">
${header(label, dateLine(doc.date))}
<div class="main"><div class="eyebrow">${esc(eyebrowTxt)}</div>
${hero}<div class="rule"></div>${body}${factHtml}</div>
<div class="foot"><span></span><b>ndhorizon.com</b></div>
</div></body></html>`;

(async () => {
  const b = await chromium.launch();
  const p = await b.newPage({ viewport: { width: 1080, height: 1350 }, deviceScaleFactor: 1 });
  await p.setContent(html, { waitUntil: "load" });
  await p.evaluate(() => document.fonts.ready);
  const over = await p.evaluate(() => document.querySelector(".wrap").scrollHeight > 1350);
  // JPG keeps the email attachment near 150 KB (the grained PNG was about 2 MB and too big for the tasks to attach).
  await p.screenshot(/\.jpe?g$/i.test(out) ? { path: out, type: "jpeg", quality: 82 } : { path: out });
  await b.close();
  console.log(JSON.stringify({ png: out, sport, date: doc.date, id: post.id, kind: post.kind, lines: n, overflow: over, text: post.text }, null, 1));
})();
